const LEGACY_STORAGE_KEYS=['simids_tanjung_lago_v5','simids_tanjung_lago_v4','simids_tanjung_lago_v3','simids_tanjung_lago_v2'];
const REMINDER_SEEN_KEY='simids_tanjung_lago_reminder_seen';
const VACCINES=[
{id:'HB0',label:'HB0',excel:false,input:true},{id:'HB0_24',label:'HB0 (<24 Jam)',excel:true},{id:'HB0_1_7',label:'HB0 (1-7 Hari)',excel:true},{id:'HB0_TOTAL',label:'HB0 (Total)',excel:true,computed:true},{id:'BCG',label:'BCG',excel:true},{id:'OPV1',label:'OPV-1',excel:true},{id:'DPT_HB_HIB1',label:'DPT/HB-Hib-1',excel:true},{id:'HEXA1',label:'DPT/HB-Hib-IPV (Heksavalen)-1',excel:true},{id:'OPV2',label:'OPV-2',excel:true},{id:'PCV1',label:'Pneumokokus-1',excel:true},{id:'ROTA1',label:'Rotavirus-1',excel:true},{id:'DPT_HB_HIB2',label:'DPT/HB-Hib-2',excel:true},{id:'HEXA2',label:'DPT/HB-Hib-IPV (Heksavalen)-2',excel:true},{id:'OPV3',label:'OPV-3',excel:true},{id:'PCV2',label:'Pneumokokus-2',excel:true},{id:'DPT_HB_HIB3',label:'DPT/HB-Hib-3',excel:true},{id:'HEXA3',label:'DPT/HB-Hib-IPV (Heksavalen)-3',excel:true},{id:'OPV4',label:'OPV-4',excel:true},{id:'IPV1',label:'IPV-1',excel:true},{id:'ROTA2',label:'Rotavirus-2',excel:true},{id:'ROTA3',label:'Rotavirus-3',excel:true},{id:'MR1',label:'Campak-Rubella (MR)-1',excel:true},{id:'IPV2',label:'IPV-2',excel:true},{id:'IPV3',label:'IPV-3 (Khusus DIY)',excel:true},{id:'IBL',label:'Imunisasi Bayi Lengkap',excel:true},{id:'MR2',label:'Campak-Rubella (MR)-2',excel:false,program:true}
];
