function reminderItems(){return riskList().filter(x=>['overdue','due','mr2'].includes(x.r.status)).sort((a,b)=>{const order={overdue:0,due:1,mr2:2};const d=order[a.r.status]-order[b.r.status];if(d)return d;return String(a.r.due||'').localeCompare(String(b.r.due||''))})}
function updateReminderBadges(){const n=reminderItems().length;['headerReminderCount','sideReminderCount','quickReminderCount','bottomReminderCount'].forEach(id=>{const el=document.getElementById(id);if(el){el.textContent=n;el.style.display=n?'grid':'none'}})}
function renderReminderCenter(){const items=reminderItems(),list=document.getElementById('reminderList'),title=document.getElementById('reminderTitle'),sub=document.getElementById('reminderSubtitle');if(!list)return;if(!items.length){title.textContent='Tidak ada pengingat mendesak';sub.textContent='Semua jadwal yang tercatat masih aman.';list.innerHTML='<div class="empty">✓ Tidak ada orang tua yang perlu dihubungi saat ini.</div>';return}const over=items.filter(x=>x.r.status==='overdue').length,due=items.filter(x=>x.r.status==='due').length,mr2=items.filter(x=>x.r.status==='mr2').length;title.textContent=`${items.length} anak perlu diperhatikan`;sub.textContent=`${over} jadwal lewat • ${due} jadwal dekat • ${mr2} MR-2 belum tercatat. Mulai dari yang paling atas.`;list.innerHTML=items.slice(0,5).map(({c,r})=>{const wa=waLink(c,r);return `<div class="reminder-item ${r.status==='overdue'?'urgent':''}"><div><b>${esc(c.name)}</b><small>${esc(c.parentName)} • ${esc(c.hamlet)}</small><span class="due-text ${r.status==='due'?'warn':''}">${esc(r.label)}${r.due?' • '+fmtDate(r.due):''}</span></div>${wa?`<a class="mini-btn wa-btn" href="${wa}" target="_blank" rel="noopener">💬 WhatsApp</a>`:'<span class="tag neutral">No. WA kosong</span>'}</div>`}).join('')+(items.length>5?`<div class="empty">+ ${items.length-5} anak lainnya. Tekan “Lihat semua pengingat”.</div>`:'')}
