const SEARCHABLE_SELECT_IDS=['childVillage','childPosyandu','eventServicePlace','childVillageFilter','riskVillageFilter','eduVillage','assessmentVillage','reportVillageFilter','settingFocusVillage'];
function foldText(v=''){return String(v).toLocaleLowerCase('id-ID').normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function fullDate(v){if(!v)return '-';return new Date(v+'T00:00:00').toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function latestEventTime(childId){const e=[...childEvents(childId)].sort((a,b)=>b.date.localeCompare(a.date))[0];return e?.date||''}
