  const c=state.children.find(x=>x.id===document.getElementById('eventChild').value),v=VACCINES.find(x=>x.id===document.getElementById('eventVaccine').value),date=document.getElementById('eventDate').value,place=document.getElementById('eventServicePlace')?.value||'';
