function openVaccinePicker(){const childId=document.getElementById('eventChild').value;if(!childId){openChildPicker();return}vaccinePickerFilter='missing';document.querySelectorAll('[data-vaccine-filter]').forEach(b=>b.classList.toggle('active',b.dataset.vaccineFilter==='missing'));const input=document.getElementById('vaccinePickerSearch');if(input)input.value='';renderVaccinePickerResults('');pickerOpen('vaccinePickerModal');setTimeout(()=>input?.focus(),120)}
function renderVaccinePickerResults(query=''){
  const childId=document.getElementById('eventChild').value,q=foldText(query.trim()),out=document.getElementById('vaccinePickerResults');if(!out)return;
  const counts={};const latest={};childEvents(childId).forEach(e=>{counts[e.vaccineId]=(counts[e.vaccineId]||0)+1;if(!latest[e.vaccineId]||e.date>latest[e.vaccineId])latest[e.vaccineId]=e.date});
  let items=VACCINES.filter(v=>!v.computed).filter(v=>vaccinePickerFilter==='all'||KOHORT_INPUT_IDS.includes(v.id)).filter(v=>!q||foldText(`${v.id} ${v.label}`).includes(q));
  if(vaccinePickerFilter==='missing'&&!q){const missing=items.filter(v=>!counts[v.id]);if(missing.length)items=missing}
  if(!items.length){out.innerHTML='<div class="picker-empty"><b>Tidak ditemukan</b>Coba kata lain atau pilih “Semua imunisasi”.</div>';return}
  const selected=document.getElementById('eventVaccine').value;
  out.innerHTML=items.map(v=>{const done=counts[v.id]||0;return `<button type="button" class="picker-option ${done?'done':''} ${selected===v.id?'selected':''}" data-pick-vaccine="${v.id}"><span class="option-icon">${done?'✓':esc(v.id.replaceAll('_','-').replace('DPT-HB-HIB','DPT').slice(0,5))}</span><span class="option-main"><b>${esc(v.label)}</b><small>${done?`Sudah tercatat ${done}x${latest[v.id]?' • terakhir '+fmtDate(latest[v.id]):''}`:'Belum tercatat untuk anak ini'}</small></span><span class="option-state">${selected===v.id?'Dipilih':done?'Sudah ada':'Pilih'}</span></button>`}).join('')
}
