function showImmunizationSuccess(child,vaccine,date){const box=document.getElementById('immunizationSuccess');if(!box)return;box.hidden=false;box.innerHTML=`<div class="success-wrap"><span class="success-icon">✓</span><div><b>Data berhasil disimpan</b><p>${esc(child?.name||'-')} • ${esc(vaccine?.label||'-')} • ${esc(fullDate(date))}</p><div class="success-actions"><button class="btn primary" type="button" id="sameChildBtn">＋ Imunisasi lain, anak yang sama</button><button class="btn secondary" type="button" id="nextChildBtn">Anak berikutnya</button><button class="btn secondary" type="button" id="closeSuccessBtn">Selesai</button></div></div></div>`;box.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>{document.getElementById('sameChildBtn')?.addEventListener('click',()=>{box.hidden=true;document.getElementById('eventChild').value=child.id;document.getElementById('eventDate').value=date||today();prefillServicePlaceForChild(child.id);syncImmunizationPickerLabels();renderSelectedChild();openVaccinePicker()});document.getElementById('nextChildBtn')?.addEventListener('click',()=>{box.hidden=true;openChildPicker()});document.getElementById('closeSuccessBtn')?.addEventListener('click',()=>{box.hidden=true;showPage('home')})},0)}
function searchableLabel(select){return select?.options[select.selectedIndex]?.text||'Pilih'}
function initSearchableSelects(){SEARCHABLE_SELECT_IDS.forEach(id=>{const select=document.getElementById(id);if(!select||select.dataset.searchEnhanced)return;select.dataset.searchEnhanced='1';select.classList.add('searchable-select-native');const shell=document.createElement('div');shell.className='searchable-select-shell';select.parentNode.insertBefore(shell,select);shell.appendChild(select);const btn=document.createElement('button');btn.type='button';btn.className='searchable-select-button';btn.dataset.selectTarget=id;btn.innerHTML='<span></span>';shell.appendChild(btn);btn.addEventListener('click',()=>openGenericSelect(id));select.addEventListener('change',()=>refreshSearchableButtons())});refreshSearchableButtons()}
function refreshSearchableButtons(){SEARCHABLE_SELECT_IDS.forEach(id=>{const select=document.getElementById(id),btn=document.querySelector(`[data-select-target="${id}"]`);if(select&&btn){const span=btn.querySelector('span');if(span)span.textContent=searchableLabel(select)}})}
function genericSelectTitle(id){return ({childVillage:'Pilih desa anak',childVillageFilter:'Filter desa',riskVillageFilter:'Filter desa',eduVillage:'Pilih desa kegiatan',assessmentVillage:'Pilih desa peserta',reportVillageFilter:'Pilih desa laporan',settingFocusVillage:'Pilih desa fokus',childPosyandu:'Pilih Posyandu / pos utama',eventServicePlace:'Pilih Pos Imunisasi'})[id]||'Pilih data'}
function openGenericSelect(id){const select=document.getElementById(id);if(!select)return;genericSelectTarget=id;document.getElementById('genericSelectTitle').textContent=genericSelectTitle(id);const input=document.getElementById('genericSelectSearch');input.value='';renderGenericSelectResults('');pickerOpen('genericSelectModal');setTimeout(()=>input.focus(),120)}
function renderGenericSelectResults(query=''){const select=document.getElementById(genericSelectTarget),out=document.getElementById('genericSelectResults');if(!select||!out)return;const q=foldText(query),opts=[...select.options].filter(o=>!q||foldText(o.text).includes(q));out.innerHTML=opts.length?opts.map(o=>`<button type="button" class="picker-option ${o.value===select.value?'selected':''}" data-generic-option="${esc(o.value)}"><span class="option-icon">⌖</span><span class="option-main"><b>${esc(o.text)}</b></span>${o.value===select.value?'<span class="option-state">Dipilih</span>':''}</button>`).join(''):'<div class="picker-empty"><b>Tidak ditemukan</b>Coba ketik nama lain.</div>'}
function chooseGenericOption(value){const select=document.getElementById(genericSelectTarget);if(!select)return;select.value=value;select.dispatchEvent(new Event('change',{bubbles:true}));refreshSearchableButtons();pickerClose('genericSelectModal')}
function bindPickerEvents(){
  document.getElementById('openChildPicker')?.addEventListener('click',openChildPicker);document.getElementById('openVaccinePicker')?.addEventListener('click',openVaccinePicker);
  document.getElementById('childPickerSearch')?.addEventListener('input',e=>renderChildPickerResults(e.target.value));document.getElementById('vaccinePickerSearch')?.addEventListener('input',e=>renderVaccinePickerResults(e.target.value));document.getElementById('genericSelectSearch')?.addEventListener('input',e=>renderGenericSelectResults(e.target.value));
  document.getElementById('pickerAddChildBtn')?.addEventListener('click',()=>{pickerClose('childPickerModal');showPage('children');const c=document.getElementById('childFormCard');c.classList.add('open');document.getElementById('childFormTitle').textContent='Tambah Anak';setTimeout(()=>document.getElementById('childName')?.focus(),100)});
  document.querySelectorAll('[data-close-picker]').forEach(b=>b.addEventListener('click',()=>pickerClose(b.dataset.closePicker)));
  document.querySelectorAll('.picker-modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)pickerClose(m.id)}));
  document.body.addEventListener('click',e=>{const c=e.target.closest('[data-pick-child]');if(c)chooseChild(c.dataset.pickChild);const v=e.target.closest('[data-pick-vaccine]');if(v)chooseVaccine(v.dataset.pickVaccine);const g=e.target.closest('[data-generic-option]');if(g)chooseGenericOption(g.dataset.genericOption);const f=e.target.closest('[data-vaccine-filter]');if(f){vaccinePickerFilter=f.dataset.vaccineFilter;document.querySelectorAll('[data-vaccine-filter]').forEach(x=>x.classList.toggle('active',x===f));renderVaccinePickerResults(document.getElementById('vaccinePickerSearch').value)}})
}

