function csvCell(v){if(typeof v==='string'&&/^[=+@\-\t\r]/.test(v))v="'"+v;return `"${String(v??'').replace(/"/g,'""')}"`}
function exportCsv(){
  const village=document.getElementById('reportVillageFilter').value||'all',month=Number(document.getElementById('reportMonthFilter').value||12),vaccines=VACCINES.filter(v=>v.excel);
  const h1=['NO','PUSKESMAS','DESA','SASARAN PUSDATIN','','','','','','SASARAN DAERAH','','','','','','HASIL IMUNISASI BAYI',...Array(Math.max(0,vaccines.length*6-1)).fill('')];
  const h2=['','','','BAYI BARU LAHIR','','','SURVIVING INFANTS','','','BAYI BARU LAHIR','','','SURVIVING INFANTS','','',...vaccines.flatMap(v=>[v.label,'','','','',''])];
  const h3=['','','','L','P','JUMLAH','L','P','JUMLAH','L','P','JUMLAH','L','P','JUMLAH',...vaccines.flatMap(()=>['# L','%','# P','%','# JML','%'])];
  const selected=village==='all'?state.targets:state.targets.filter(t=>t.name===village),rows=selected.map((t,i)=>excelRowData(t,i,month,false));if(village==='all')rows.push(excelRowData(aggregateTarget(state.targets),0,month,true));
  const csv='\ufeff'+[h1,h2,h3,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n');download(csv,`SiMIDS_Format_Excel_${village}_${state.settings.year}_${String(month).padStart(2,'0')}.csv`,'text/csv;charset=utf-8')
}
const KOHORT_EXPORT_MAP=[
['HB0',['HB0','HB0_24','HB0_1_7','HB0_TOTAL']],['BCG 1',['BCG']],['POLIO 1',['OPV1']],['POLIO 2',['OPV2']],['POLIO 3',['OPV3']],['POLIO 4',['OPV4']],
['DPT-Hb-Hib 1',['DPT_HB_HIB1']],['DPT-Hb-Hib 2',['DPT_HB_HIB2']],['DPT-Hb-Hib 3',['DPT_HB_HIB3']],['IPV 1',['IPV1']],['IPV 2',['IPV2']],
['ROTA 1',['ROTA1']],['ROTA 2',['ROTA2']],['ROTA 3',['ROTA3']],['PCV 1',['PCV1']],['PCV 2',['PCV2']],['MR 1',['MR1']]
];
function kohortEvent(childId,ids){return [...state.events].filter(e=>e.childId===childId&&ids.includes(e.vaccineId)).sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]||null}
function exportIndividualKohort(){
  const headers=['NIK Anak','Nama Anak','Tanggal Lahir Anak','Jenis Kelamin Anak','Nama Orang Tua','Provinsi','Kabupaten atau Kota','Kecamatan','Kelurahan atau Desa','Puskesmas'];
  KOHORT_EXPORT_MAP.forEach(([label])=>headers.push(`Tanggal Imunisasi ${label}`,`Tanggal Input ${label}`,`Pos Imunisasi ${label}`));
  headers.push('Tanggal IDL 1','Tanggal Input IDL 1','Pos IDL 1','PKM Pembentuk IDL 1','Status IDL 1');
  const kids=[...state.children].sort((a,b)=>(a.name||'').localeCompare(b.name||'','id'));
  const rows=kids.map(c=>{
    const row=[c.nik||'',c.name||'',c.dob||'',c.sex==='L'?'Laki-laki':'Perempuan',c.parentName||'',c.province||DEFAULT_AREA.province,c.district||DEFAULT_AREA.district,c.subdistrict||DEFAULT_AREA.subdistrict,c.village||'',c.puskesmas||DEFAULT_AREA.puskesmas];
    KOHORT_EXPORT_MAP.forEach(([,ids])=>{const e=kohortEvent(c.id,ids);row.push(e?.date||'',e?.inputDate||'',e?.servicePlace||'')});
    row.push(c.idlDate||'',c.idlInputDate||'',c.idlPlace||'',c.idlPkm||'',c.idlStatus||'');
    return row;
  });
  const csv='\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n');
  download(csv,`SiMIDS_Kohort_Individu_${today()}.csv`,'text/csv;charset=utf-8')
}
function download(data,name,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
